// Development-only controls wrapper
// This file will be tree-shaken out of production builds

const isDevelopment = import.meta.env.DEV;

// Mock controls for production
const mockControls = {
  value: false,
  min: 0,
  max: 1,
  step: 0.1,
  label: '',
  options: [],
  onChange: () => {},
  onUpdate: () => {},
};

// Mock useControls for production
const mockUseControls = (config) => {
  if (typeof config === 'string') {
    return mockControls;
  }
  
  if (config && typeof config === 'object') {
    const result = {};
    for (const [key, value] of Object.entries(config)) {
      if (typeof value === 'object' && value !== null) {
        if (value.value !== undefined) {
          result[key] = value.value;
        } else {
          result[key] = mockUseControls(value);
        }
      } else {
        result[key] = value;
      }
    }
    return result;
  }
  
  return mockControls;
};

// Mock folder for production
const mockFolder = (config, options) => {
  return mockUseControls(config);
};

// Mock Leva component for production
const MockLeva = () => null;

// Export production mocks by default
export const useControls = mockUseControls;
export const folder = mockFolder;
export const Leva = MockLeva;

// In development, override with real Leva
if (isDevelopment) {
  // Dynamic import to avoid bundling in production
  import('leva').then((levaModule) => {
    // Override the exports with real Leva
    Object.assign(exports, {
      useControls: levaModule.useControls,
      folder: levaModule.folder,
      Leva: levaModule.Leva,
    });
  }).catch((error) => {
    console.warn('Failed to load Leva in development:', error);
  });
} 